'use strict';

// MODULES //

import constantFunction from '@stdlib/utils-constant-function';
import { factory as degenerate } from '@stdlib/stats-base-dists-degenerate-cdf';
import erfcx from '@stdlib/math-base-special-erfcx';
import isnan from '@stdlib/math-base-assert-is-nan';
import sqrt from '@stdlib/math-base-special-sqrt';
import erfc from '@stdlib/math-base-special-erfc';
import exp from '@stdlib/math-base-special-exp';
import PINF from '@stdlib/constants-float64-pinf';


// MAIN //

/**
* Returns a function for evaluating the cumulative distribution function (CDF) for a Wald distribution.
*
* @param {PositiveNumber} mu - mean
* @param {NonNegativeNumber} lambda - shape parameter
* @returns {Function} function to evaluate the cumulative distribution function
*
* @example
* var cdf = factory( 1.0, 1.0 );
* var y = cdf( 2.0 );
* // returns ~0.885
*
* y = cdf( 0.5 );
* // returns ~0.365
*/
function factory( mu, lambda ) {
	if (
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda < 0.0
	) {
		return constantFunction( NaN );
	}
	if ( lambda === 0.0 ) {
		return degenerate( mu );
	}
	return cdf;

	/**
	* Evaluates the cumulative distribution function (CDF) of a Wald distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {Probability} evaluated CDF
	*
	* @example
	* var y = cdf( 2.0 );
	* // returns <number>
	*/
	function cdf( x ) {
		var t1;
		var t2;
		var a;
		var b;
		var z;

		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x <= 0.0 ) {
			return 0.0;
		}
		if ( x === PINF ) {
			return 1.0;
		}
		z = sqrt( lambda / x );
		a = ( z * ( ( x / mu ) - 1.0 ) ) / sqrt( 2.0 );
		b = ( z * ( ( x / mu ) + 1.0 ) ) / sqrt( 2.0 );

		// Φ(a) = 0.5 * erfc( -a / √2 )
		t1 = 0.5 * erfc( -a );

		// exp( 2λ/μ ) * erfc( b ) = erfcx( b ) * exp( -a² ), as b² - a² = 2λ/μ; computing via `erfcx` avoids overflow of the exponential term for large `λ/μ`:
		t2 = 0.5 * erfcx( b ) * exp( -a * a );
		return t1 + t2;
	}
}


// EXPORTS //

export default factory;
